definition.script:
pipeline {
    agent any

    environment {
        GIT_BRANCH = 'main'
        GIT_REPO_URL = 'https://github.com/yogeshvk1209/microservice_k8s'
        AWS_REGION = 'us-east-1'
        Docker_REPO = 'yogeshvk1209'
        DOCKER_IMAGE_NAME = 'httppy_cent9'
        KUBECONFIG = "/var/lib/jenkins/.kube/config" //locate in jenkins EC2 serevr
    }
    parameters {
        string(name: 'GIT_REPO_URL', defaultValue: 'https://github.com/yourusername/microservice_k8s.git', description: 'Git repository URL')
        string(name: 'GIT_BRANCH', defaultValue: 'main', description: 'Git branch to build')
        string(name: 'Deployment_PATH', defaultValue: 'jenkins/Dockerfile', description: 'Path to Dockerfile')
        string(name: 'Deployment_CONTEXT_PATH', defaultValue: '.', description: 'Path to Docker build context')
        string(name: 'IMAGE_NAME', defaultValue: 'jenkins2.504_jdk21', description: 'Name of the Docker image')
        string(name: 'IMAGE_TAG', defaultValue: 'latest', description: 'Tag for the Docker image')
        string(name: 'APP_NAME', defaultValue: 'httppy_cent9', description: 'APP to be deployed')
    }
       stages {
        stage('Checkout') {
            steps {
                // Clean workspace before building
                cleanWs()

                // Checkout code from Git
                git branch: params.GIT_BRANCH,
                    url: params.GIT_REPO_URL
            }
        }
        stage('Deploy to EKS') {
            steps {
                script {
                    // Set KUBECONFIG environment variable
                    dir(params.Deployment_CONTEXT_PATH) {
                    withEnv(["KUBECONFIG=${KUBECONFIG}"]) {
                        sh "kubectl apply -f ${params.Deployment_PATH}/${params.APP_NAME}-deployment.yaml"
                    }
                    }
                }
            }

        }
        }
}
